using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class ApprovalGroupTests
{
 class FutureTime:TimeProvider{public override DateTimeOffset GetUtcNow()=>DateTimeOffset.UtcNow.AddHours(2);}
 class User(int id,int? emp,bool admin=false):ICurrentUser{public string Email=>$"group{id}@example.local";public int? EmployeeId=>emp;public int UserId=>id;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>admin;public bool Can(string p)=>admin;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));foreach(var emp in await d.Set<Employee>().Where(e=>e.Id>=7&&e.Id<=10).ToListAsync())emp.Status=EmployeeStatus.Active;await d.SaveAsync();return d;}
 static WorkflowService W(AppDbContext d){var u=new User(1,1,true);return new(d,u,new(d,u,new(TimeProvider.System)));}
 static ApprovalService A(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,new(d,u),u,a,new(d,u,c),c,W(d),new(d,u,a,c));}
 static async Task<AppUser> Account(AppDbContext d,int emp,string suffix=""){var u=new AppUser{EmployeeId=emp,Email=$"group{emp}{suffix}@example.local",RoleList=Roles.HRManager,IsActive=true,PasswordHash="unused"};d.Add(u);await d.SaveAsync();return u;}
 static async Task<OvertimeRequest> Request(AppDbContext d,int count=2){var r=new OvertimeRequest{EmployeeId=6,Date=new(2026,12,1),Hours=1,Route=ApprovalStage.GroupToken(count,[7,8])};d.Add(r);await d.SaveAsync();return r;}
 [Theory][InlineData(1)][InlineData(2)]public async Task CapturedCountDoesNotAdvanceEarlyAndOnlyDistinctHumansCount(int count){await using var d=await Db();var u=await Account(d,7);var v=await Account(d,8);var r=await Request(d,count);await A(d,new(u.Id,7)).ApproveAsync("Overtime",r.Id,"first");Assert.Equal(count==1?RequestStatus.Approved:RequestStatus.Pending,r.Status);if(count==2){Assert.Equal(0,r.StageIndex);var alias=await Account(d,7,"alias");await Assert.ThrowsAsync<DomainException>(()=>A(d,new(alias.Id,7)).ApproveAsync("Overtime",r.Id,"repeat"));await A(d,new(v.Id,8)).ApproveAsync("Overtime",r.Id,"second");r=(await d.Set<OvertimeRequest>().FindAsync(r.Id))!;Assert.Equal(RequestStatus.Approved,r.Status);}Assert.Equal(count,await d.Set<ApprovalVote>().CountAsync());Assert.Equal(count,await d.Set<ApprovalAction>().CountAsync(x=>x.Kind=="Overtime"&&x.RequestId==r.Id));}
 [Fact]public async Task AdminCannotBypassAndDelegateCannotFillTwoSeats(){await using var d=await Db();var u=await Account(d,7);await Account(d,8);var del=await Account(d,9);d.AddRange(new Delegation{FromEmployeeId=7,ToEmployeeId=9,StartDate=DateTime.Today.AddDays(-1),EndDate=DateTime.Today.AddDays(1)},new Delegation{FromEmployeeId=8,ToEmployeeId=9,StartDate=DateTime.Today.AddDays(-1),EndDate=DateTime.Today.AddDays(1)});await d.SaveAsync();var r=await Request(d);await Assert.ThrowsAsync<DomainException>(()=>A(d,new(1,1,true)).ApproveAsync("Overtime",r.Id,"admin bypass"));await A(d,new(del.Id,9)).ApproveAsync("Overtime",r.Id,"delegate");await Assert.ThrowsAsync<DomainException>(()=>A(d,new(del.Id,9)).ApproveAsync("Overtime",r.Id,"second seat"));Assert.Single(await d.Set<ApprovalVote>().ToListAsync());}
 [Fact]public async Task ReassignmentReplacesOneUnvotedSeatNotTheQuorum(){await using var d=await Db();var u=await Account(d,7);var v=await Account(d,8);var replacement=await Account(d,9);var r=await Request(d);await A(d,new(1,1,true)).ReassignAsync("Overtime",r.Id,0,replacement.Id,"absence",7);await Assert.ThrowsAsync<DomainException>(()=>A(d,new(u.Id,7)).ApproveAsync("Overtime",r.Id,"old seat"));await A(d,new(replacement.Id,9)).ApproveAsync("Overtime",r.Id,"replacement");Assert.Equal(RequestStatus.Pending,(await d.Set<OvertimeRequest>().FindAsync(r.Id))!.Status);await Assert.ThrowsAsync<DomainException>(()=>A(d,new(1,1,true)).ReassignAsync("Overtime",r.Id,0,u.Id,"voted seat",7));await A(d,new(v.Id,8)).ApproveAsync("Overtime",r.Id,"other seat");Assert.Equal(RequestStatus.Approved,(await d.Set<OvertimeRequest>().FindAsync(r.Id))!.Status);}
 [Theory][InlineData(true)][InlineData(false)]public async Task RejectOrRecallKeepsVotesButEndsRequest(bool reject){await using var d=await Db();var u=await Account(d,7);var v=await Account(d,8);var r=await Request(d);await A(d,new(u.Id,7)).ApproveAsync("Overtime",r.Id,"one vote");if(reject)await A(d,new(v.Id,8)).RejectAsync("Overtime",r.Id,"rejected");else await A(d,new(99,6)).CancelAsync("Overtime",r.Id);Assert.Single(await d.Set<ApprovalVote>().ToListAsync());await Assert.ThrowsAsync<DomainException>(()=>A(d,new(v.Id,8)).ApproveAsync("Overtime",r.Id,"too late"));Assert.Equal(reject?RequestStatus.Rejected:RequestStatus.Cancelled,(await d.Set<OvertimeRequest>().FindAsync(r.Id))!.Status);}
 [Fact]public async Task RosterCapturedAtSubmissionDeduplicatesAccountsAndIgnoresLaterRoleEdits(){await using var d=await Db();await Account(d,7);await Account(d,7,"alias");await Account(d,8);var w=W(d);await w.AddStepAsync("Overtime",ApproverType.Role,[Roles.HRManager],null,ApprovalRule.Quorum,2);var e=(await d.Set<Employee>().FindAsync(6))!;var r=new OvertimeRequest{EmployeeId=6};await w.RouteRequestAsync("Overtime",r,e,1);var token=r.Stages.Last();var group=ApprovalStage.Group(token)!.Value;Assert.Equal(2,group.Required);Assert.Equal(1,group.Employees.Count(x=>x==7));Assert.DoesNotContain(6,group.Employees);var saved=r.Route;foreach(var u in await d.Set<AppUser>().Where(x=>x.EmployeeId==7).ToListAsync())u.RoleList=Roles.Employee;await d.SaveAsync();Assert.Equal(saved,r.Route);}
 [Fact]public async Task InvalidConfigurationAndInsufficientRosterBlockRatherThanDowngrade(){await using var d=await Db();var w=W(d);await Assert.ThrowsAsync<DomainException>(()=>w.AddStepAsync("Overtime",ApproverType.DirectManager,null,null,ApprovalRule.All));await Assert.ThrowsAsync<DomainException>(()=>w.AddStepAsync("Overtime",ApproverType.Role,[Roles.HRManager],null,ApprovalRule.Quorum,0));await w.AddStepAsync("Overtime",ApproverType.Role,[Roles.HRManager],null,ApprovalRule.Quorum,1000);var e=(await d.Set<Employee>().FindAsync(6))!;await Assert.ThrowsAsync<DomainException>(()=>w.RouteRequestAsync("Overtime",new OvertimeRequest(),e,1));Assert.DoesNotContain(d.ChangeTracker.Entries<WorkflowRevision>(),x=>x.State==EntityState.Added);}
 [Fact]public async Task VotesAreAppendOnly(){await using var d=await Db();var u=await Account(d,7);await Account(d,8);var r=await Request(d);await A(d,new(u.Id,7)).ApproveAsync("Overtime",r.Id,"evidence");var vote=await d.Set<ApprovalVote>().SingleAsync();vote.ActorEmployeeId=99;await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task NotificationsAndRemindersExcludeNonParticipantsAndCompletedVoters(){await using var d=await Db();var u=await Account(d,7);var v=await Account(d,8);var outsider=await Account(d,9);var r=await Request(d);r.CreatedAt=DateTime.UtcNow.AddHours(-6);await d.SaveAsync();var c=new AppClock(TimeProvider.System);await new NotificationService(d,new User(1,1,true),c).NotifyStageAsync(r,"group check");await d.SaveAsync();Assert.DoesNotContain(await d.Set<Notification>().Where(x=>x.Details=="group check").ToListAsync(),x=>x.UserId==outsider.Id);await A(d,new(u.Id,7)).ApproveAsync("Overtime",r.Id,"first");d.Add(new AppSetting{Key="Workflow.ReminderHours.Overtime",Value="1"});await d.SaveAsync();await new ApprovalReminders(d,new AppClock(new FutureTime())).RunAsync();var reminders=await d.Set<ApprovalReminder>().Where(x=>x.Kind=="Overtime"&&x.RequestId==r.Id).ToListAsync();Assert.DoesNotContain(reminders,x=>x.UserId==u.Id||x.UserId==outsider.Id);Assert.Contains(reminders,x=>x.UserId==v.Id);}

 [Theory][InlineData(ApprovalRule.All)][InlineData(ApprovalRule.CapturedAny)]public async Task ExplicitAllAndOneResolveCounts(ApprovalRule rule){await using var d=await Db();await Account(d,7);await Account(d,8);await W(d).AddStepAsync("Overtime",ApproverType.Role,[Roles.HRManager],null,rule);var e=(await d.Set<Employee>().FindAsync(6))!;var r=new OvertimeRequest{EmployeeId=6};await W(d).RouteRequestAsync("Overtime",r,e,1);var group=ApprovalStage.Group(r.Stages.Last())!.Value;Assert.Equal(rule==ApprovalRule.All?group.Employees.Length:1,group.Required);}
 [Fact]public async Task DeactivationBlocksCapturedParticipantButDoesNotShrinkCount(){await using var d=await Db();var u=await Account(d,7);await Account(d,8);var r=await Request(d);u.IsActive=false;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>A(d,new(u.Id,7)).ApproveAsync("Overtime",r.Id,"inactive"));Assert.Equal(2,ApprovalStage.Group((await d.Set<OvertimeRequest>().FindAsync(r.Id))!.CurrentStage)!.Value.Required);}
 [Fact]public async Task FinalApplyFailureRollsBackVoteAndLeavesPending(){await using var d=await Db();var u=await Account(d,7);var v=await Account(d,8);var day=new DateTime(2026,12,1);var r=new AttendanceCorrection{EmployeeId=6,Date=day,NewCheckIn=day.AddHours(9),NewCheckOut=day.AddHours(17),Reason="Fictional",Route=ApprovalStage.GroupToken(2,[7,8])};d.Add(r);var locked=new AttendancePeriodLock{EmployeeId=6,Year=2026,Month=12};d.Add(locked);await d.SaveAsync();await A(d,new(u.Id,7)).ApproveAsync("Correction",r.Id,"first");await Assert.ThrowsAsync<DomainException>(()=>A(d,new(v.Id,8)).ApproveAsync("Correction",r.Id,"blocked by lock"));Assert.Single(await d.Set<ApprovalVote>().Where(x=>x.Kind=="Correction"&&x.RequestId==r.Id).ToListAsync());Assert.Equal(RequestStatus.Pending,(await d.Set<AttendanceCorrection>().FindAsync(r.Id))!.Status);}
 [Fact]public async Task EveryVoteTouchesRequestRevisionForOptimisticContention(){await using var d=await Db();var u=await Account(d,7);await Account(d,8);var r=await Request(d);var before=d.Entry(r).Property<string>("Revision").CurrentValue;await A(d,new(u.Id,7)).ApproveAsync("Overtime",r.Id,"first");Assert.NotEqual(before,d.Entry(r).Property<string>("Revision").CurrentValue);Assert.NotEmpty(r.AssignmentStamp);}
}
